export const BODY: string = "\n<p>Двести килобайт — это размер, при котором фото для интернета выглядят почти как оригинал. Страницы остаются быстрыми, а изображения — убедительными.</p>\n<p>Блоги, интернет-магазины и портфолио стандартизируют именно 200 КБ. Это достаточно много для деталей и достаточно мало для скорости.</p>\n<p>Это руководство объясняет, почему 200 КБ стали стандартом, как сжатие достигает этого размера и как получить максимум качества.</p>\n<h2 id=\"why-200kb\">Почему именно 200 КБ</h2>\n<p>При 200 КБ типичное фото выглядит почти неотличимо от оригинала. Только сравнение на уровне пикселей выдаёт сжатие.</p>\n<p>Этот размер проходит почти все лимиты загрузки для интернета. Порталы, которые требуют 50 или 100 КБ, — исключение, а не правило для веба.</p>\n<p>Для страниц 200 КБ — разумный бюджет на одно изображение. Десять таких изображений весят 2 МБ, что современные соединения выдерживают легко.</p>\n<p>Поэтому 200 КБ — это значение по умолчанию для веба, когда лимит не указан. Оно балансирует качество и скорость лучше других размеров.</p>\n<h2 id=\"how-the-tool-works\">Как работает инструмент для 200 КБ</h2>\n<p><a href=\"/ru/szhat-izobrazhenie-do-200-kb/\">Инструмент сжатия изображения до 200 КБ</a> полностью работает в вашем браузере. Изображение никогда не загружается на сервер.</p>\n<p>Он использует бинарный поиск качества: проверяет уровни качества, пока не найдёт самый высокий, который укладывается в 200 КБ.</p>\n<p>Сначала — качество при полном размере. Размеры в пикселях уменьшаются, только когда одного качества недостаточно.</p>\n<p>Принимаются файлы до 25 МБ, включая JPG, PNG, WebP и HEIC. Фото с камеры или из зеркальной камеры подходит отлично.</p>\n<h2 id=\"quality-at-200kb\">Качество при 200 КБ</h2>\n<p>При 200 КБ большинство зрителей вообще не заметят сжатия. Различия видны, только если приблизить изображение и искать их специально.</p>\n<p>Текстура ткани, блеск украшений и напечатанные этикетки сохраняются. Именно эти детали продают товары, и 200 КБ их не убивают.</p>\n<p>Тона кожи остаются естественными, без пятен и пластикового эффекта. Портреты при 200 КБ выглядят профессионально.</p>\n<p>Фон тоже чистый: градиенты неба и студийные фоны показывают полосы крайне редко при таком бюджете.</p>\n<h2 id=\"ecommerce-photos\">Фото для интернет-магазинов</h2>\n<p>Фото товаров при 200 КБ сохраняют детали, которые влияют на покупку. Покупатель видит текстуру, швы и реальный цвет товара.</p>\n<p>Держите фон чистым, а товар — по центру. Аккуратный снимок сжимается лучше и выглядит профессиональнее.</p>\n<p>Используйте WebP для современных магазинов: при том же весе он даёт чуть более чистый результат. Для маркетплейсов, требующих JPG, переключайте формат и сохраняйте размеры.</p>\n<p>Проверяйте страницу товара на телефоне после загрузки. Большинство покупателей приходят с мобильных устройств, и именно там фото должно выглядеть хорошо.</p>\n<p>Сжимайте все фото товаров одним стандартом. Одинаковый вес и размеры делают каталог аккуратным и быстрым.</p>\n<h2 id=\"blogs-and-cms\">Блоги и системы управления контентом</h2>\n<p>Главные изображения статей при 200 КБ выглядят резкими на любых экранах. Читатель видит качественную картинку, а страница всё равно загружается быстро.</p>\n<p>Системы управления контентом часто сами сжимают загрузки повторно. Старт с чистого файла на 200 КБ даёт им хороший материал для работы.</p>\n<p>Держите миниатюры легче главного изображения: 100 КБ для миниатюр и 200 КБ для главного изображения — разумное разделение.</p>\n<p>Называйте файлы осмысленно: имя файла с темой статьи помогает поисковикам и вам самим при поиске в медиатеке.</p>\n<p>Проверяйте вес страницы после публикации. Даже при стандарте 200 КБ страница с двадцатью изображениями весит 4 МБ — многовато для мобильных читателей.</p>\n<h2 id=\"formats-at-200kb\">Форматы при 200 КБ</h2>\n<p>JPG — безопасный выбор при 200 КБ. Его принимают везде, и для фото он даёт отличные результаты.</p>\n<p>WebP часто чуть чище JPG при том же весе. Для современных сайтов это лучший выбор, если платформа его поддерживает.</p>\n<p>PNG подходит для графики с плоскими цветами и прозрачностью. Для фото PNG при 200 КБ всё ещё тратит бюджет впустую.</p>\n<p>Выбирайте формат по месту назначения: портал диктует правила, а не ваши предпочтения. Проверьте список принимаемых форматов заранее.</p>\n<p>Когда сомневаетесь, держите обе версии — JPG и WebP. Загрузите ту, которую примет система.</p>\n<h2 id=\"dimension-scaling\">Масштабирование размеров</h2>\n<p>Масштабирование уменьшает пиксельный размер, когда одного качества не хватает для 200 КБ. Оно происходит маленькими шагами, а не одним прыжком.</p>\n<p>Инструмент проверяет масштабы вроде 90 и 80 процентов, останавливаясь на первом, который подходит. Каждый шаг сохраняет максимум размера.</p>\n<p>Небольшой шаг обычно незаметен. Фото шириной 1200 пикселей выглядит так же при ширине 1080 пикселей на экране.</p>\n<p>Масштабирование больше всего помогает очень большим оригиналам. У фото с камеры на 24 мегапикселя намного больше пикселей, чем нужно любому экрану.</p>\n<p>Размеры можно зафиксировать, если они требуются точно. Тогда инструмент работает только с качеством и честно предупредит, если цель недостижима.</p>\n<h2 id=\"batch-200kb\">Пакетное сжатие до 200 КБ</h2>\n<p>Целую папку изображений можно сжать до 200 КБ одной партией. Перетащите файлы, и каждое будет обработано до той же цели.</p>\n<p>Результаты скачиваются вместе архивом ZIP. Так набор фото товаров или миниатюр остаётся организованным в одном месте.</p>\n<p>Пакетный режим идеален для каталогов: пятьдесят фото товаров за один раз вместо пятидесяти отдельных сжатий.</p>\n<p>Проверьте несколько результатов перед скачиванием всего архива. Если одно изображение выглядит мягким, измените его формат и запустите только его заново.</p>\n<p>Держите настройки одинаковыми для всей партии. Смешанные настройки дают смешанные результаты, которые на сайте выглядят неряшливо.</p>\n<h2 id=\"heic-and-raw\">HEIC и RAW: что нужно знать</h2>\n<p>iPhone сохраняют фото в HEIC, и инструмент читает их напрямую. Загружайте HEIC без предварительной конвертации — так результат чище.</p>\n<p>Фото HEIC уже хорошо сжаты, поэтому путь до 200 КБ у них короче. Бинарный поиск быстро находит подходящее качество.</p>\n<p>Файлы RAW — другое дело. Это необработанные данные с камеры, и перед сжатием их нужно экспортировать в JPG или PNG.</p>\n<p>Экспортируйте RAW в максимальном качестве, а затем сжимайте. Двойная потеря — сначала при экспорте, потом при сжатии — неизбежна, но при 200 КБ она почти незаметна.</p>\n<p>Не сжимайте RAW напрямую, если инструмент его не принимает. Сначала сделайте качественный экспорт, потом работайте с ним.</p>\n<h2 id=\"common-mistakes\">Типичные ошибки</h2>\n<p>Самая большая ошибка — начинать с уже сжатого файла. Каждый круг добавляет повреждения, поэтому всегда используйте оригинал.</p>\n<p>Другая ошибка — закреплять PNG для фотографии. PNG не может чисто достичь 200 КБ для детальных фото, хотя при таком бюджете это менее заметно, чем при 50 КБ.</p>\n<p>Забывать проверять результат — тоже частая ошибка. Размер файла может быть правильным, а изображение — размытым, поэтому просматривайте перед скачиванием.</p>\n<p>Не думайте, что 200 КБ подходит для печати. Это размер для интернета: для бумаги нужны оригиналы в полном разрешении.</p>\n<p>И не удаляйте оригиналы после успеха. Правила меняются, и свежая копия с оригинала делается за минуту.</p>\n<h2 id=\"when-200kb-is-wrong\">Когда 200 КБ — неправильный выбор</h2>\n<p>Когда портал требует 50 или 100 КБ, файл на 200 КБ просто не пройдёт. Лимит портала всегда важнее ваших предпочтений.</p>\n<p>Когда изображение предназначено для печати, 200 КБ мало. Для бумаги нужны сотни пикселей на дюйм, а файл на 200 КБ их не даёт.</p>\n<p>Когда страница несёт десятки изображений, общий вес становится проблемой. Двадцать изображений по 200 КБ — это 4 МБ, и для мобильных читателей это много.</p>\n<p>В таких случаях снижайте бюджет для вспомогательных изображений. Главному — 200 КБ, миниатюрам — 100 КБ или меньше.</p>\n<p>Цель всегда одна: самый большой размер, который позволяет ситуация, но не больше, чем нужно.</p>\n<h2 id=\"colour-accuracy\">Точность цвета</h2>\n<p>При 200 КБ цвета сохраняются точно. Разница между оригиналом и сжатой копией в цвете почти незаметна.</p>\n<p>Для товаров это важно: покупатель должен видеть реальный цвет. Искажённый цвет приводит к возвратам и жалобам.</p>\n<p>Проверяйте цвета на калиброванном экране, когда это возможно. Экран телефона с усиленной насыщенностью покажет не то, что увидят другие.</p>\n<p>WebP и JPG при 200 КБ передают цвета одинаково хорошо. Выбор между ними — вопрос совместимости, а не цвета.</p>\n<p>Избегайте лишних фильтров перед сжатием. Насыщенность, добавленная фильтром, тратит бюджет на цвета, которых в товаре нет.</p>\n<h2 id=\"cropping-for-shops\">Обрезка для магазинов</h2>\n<p>Обрезка перед сжатием — самый эффективный приём для фото товаров. Каждый убранный пиксель — это данные, которые компрессору не нужно хранить.</p>\n<p>Обрезайте кадр плотно вокруг товара. Пустые края тратят бюджет, который нужен деталям товара.</p>\n<p>Держите одинаковое соотношение у всех фото каталога. Сетка с одинаковыми пропорциями выглядит аккуратно и профессионально.</p>\n<p>Обрезайте оригинал, а не сжатую копию. Обрезка после сжатия отнимает качество дважды.</p>\n<p>Если маркетплейс требует квадрат, обрежьте под квадрат заранее. Сжатие квадратного кадра чище, чем сжатие широкого фото наугад.</p>\n<h2 id=\"seo-images\">Изображения и SEO</h2>\n<p>Поисковики поощряют быстрые страницы, а изображения — самая тяжёлая их часть. Держать фото около 200 КБ напрямую помогает скорости.</p>\n<p>Добавляйте описательный alt-текст каждому изображению. Поисковики не видят картинку, они читают её описание.</p>\n<p>Называйте файлы осмысленно: имя с названием товара или темой статьи помогает и поиску, и вам самим.</p>\n<p>Используйте современные форматы, где это возможно. WebP при том же качестве весит меньше, а значит, страница грузится быстрее.</p>\n<p>Проверяйте скорость страницы после замены изображений. Инструменты вроде PageSpeed Insights покажут, сколько вы выиграли.</p>\n<h2 id=\"archiving-200kb\">Архивирование копий на 200 КБ</h2>\n<p>Копии на 200 КБ — рабочие файлы, а не архив. Оригиналы храните отдельно и в полном качестве.</p>\n<p>Указывайте размер в имени файла: product-200kb.jpg сразу говорит, что внутри. Это экономит время при поиске в медиатеке.</p>\n<p>Не пережимайте архивные копии. Если нужен другой размер, сделайте свежую копию с оригинала.</p>\n<p>Делайте резервные копии оригиналов. Один сбой диска не должен уничтожить единственные копии ваших фото.</p>\n<p>Папки по проектам и датам помогают больше, чем кажется. Папка «2026-11-каталог» находится за секунды, а «Новая папка» — никогда.</p>\n<h2 id=\"measuring-success\">Как измерить успех</h2>\n<p>Успех измерить просто: файл меньше 200 КБ, изображение выглядит чисто, а место назначения принимает его без жалоб.</p>\n<p>Сравните вес оригинала и сжатой копии. Фото на 5 МБ, уменьшенное до 200 КБ, — это экономия 96 процентов.</p>\n<p>Измерьте скорость страницы до и после. Быстрая страница удерживает читателей и покупателей дольше.</p>\n<p>Ведите простую запись: исходный вес, итоговый вес и время загрузки. Числа убеждают коллег лучше любых аргументов.</p>\n<p>Если файлы перестали отклоняться, а страницы стали быстрее, процесс работает. Больше ничего доказывать не нужно.</p>\n<p>Когда готовите фото для нового магазина, начните с тестовой партии из пяти товаров. Проверьте их на странице каталога и только потом сжимайте остальные.</p>\n<p>Следите за единообразием фона: товары на разном фоне выглядят как случайный набор, а не как каталог. Один фон для всех фото делает магазин профессиональным.</p>\n<p>Если товар блестящий — украшения, стекло, металл, — проверяйте блики после сжатия. Сильное сжатие может превратить красивый блик в пятно.</p>\n<p>Для одежды важна текстура ткани: покупатель должен видеть переплетение и плотность материала. При 200 КБ текстура сохраняется, но проверяйте её в полном размере.</p>\n<p>Не забывайте про дополнительные ракурсы: фото сзади, сбоку и в деталях помогают покупателю решиться. Каждое из них тоже должно весить около 200 КБ.</p>\n<p>Когда платформа меняет требования к изображениям, обновляйте стандарт всей команды. Прошлогодние размеры могут не подойти под новую вёрстку.</p>\n<p>Держите под рукой исходники всех фото каталога. Если маркетплейс попросит другой формат или размер, свежая копия с оригинала решит задачу за минуту.</p>\n<p>Проверяйте страницу каталога после каждой большой загрузки. Один файл не того размера может сломать сетку и испортить впечатление от всего каталога.</p>\n<p>Измеряйте скорость страниц товаров до и после оптимизации. Быстрая страница не только нравится поисковикам, но и продаёт лучше: посетители не уходят, не дождавшись фото.</p>\n<p>Обучите коллег, которые фотографируют товары. Хороший исходник — ровный свет, чистый фон, резкий фокус — важнее любых настроек сжатия.</p>\n<p>Ведите простую таблицу: товар, исходный вес, итоговый вес, дата. Со временем таблица покажет, какие товары требуют особого внимания.</p>\n<p>И помните: фото товара — это не украшение, а инструмент продаж. Его задача — показать товар честно и чётко, а 200 КБ дают для этого достаточно места.</p>\n<p>Главное изображение статьи заслуживает отдельного внимания: оно первое, что видит читатель, и самое тяжёлое на странице. Дайте ему 200 КБ, а миниатюрам — меньше.</p>\n<p>Используйте srcset, чтобы браузер выбирал размер под экран: телефон получит маленькую версию, а широкий монитор — большую.</p>\n<p>Проверяйте фото товаров на экране Retina: изображение, резкое на обычном экране, на экране с высоким DPI может выглядеть мягким.</p>\n<p>Для писем держите формат JPG: некоторые почтовые клиенты плохо обрабатывают WebP, а письмо должно открываться везде.</p>\n<p>Договоритесь в команде об одном стандарте для главных изображений. Общий лимит избавляет каждого автора от догадок.</p>\n<p>Измерьте оценку PageSpeed до и после замены изображений. Запишите разницу: числа убеждают лучше впечатлений.</p>\n<p>Храните оригиналы в отдельной папке с пометкой «оригиналы». Сжатые копии — для сайта, а оригиналы — для архива и печати.</p>\n<p>Чек-лист для фото товаров: чистый фон, товар по центру, ровный свет, резкий фокус, вес около 200 КБ, формат из списка принимаемых.</p>\n<p>Если товар продаётся на нескольких площадках, готовьте версии под каждую: размеры и форматы у маркетплейсов отличаются.</p>\n<p>Покажите фото товаров коллеге, не говоря, что изменилось. Свежий взгляд замечает размытость, которую вы перестали видеть.</p>\n<p>Ведите таблицу товаров: название, исходный вес, итоговый вес, дата. Таблица показывает, какие товары требуют особого внимания.</p>\n<p>Покажите фото товаров коллеге, не говоря, что изменилось. Свежий взгляд замечает размытость, которую вы перестали видеть.</p>\n<p>Ведите таблицу товаров: название, исходный вес, итоговый вес, дата. Таблица показывает, какие товары требуют особого внимания.</p>\n<p>Двести килобайт — это вес, который легко проходит почти любую проверку, сохраняя при этом приличную детализацию.</p>\n<p>Практические шаги читайте в статье <a href=\"/ru/blog/kak-szhat-izobrazhenie-do-200-kb/\">Как сжать изображение до 200 КБ</a>. Про фото для порталов — в статье <a href=\"/ru/blog/izobrazhenie-200-kb-dlya-saytov-vakansiy-i-form/\">Изображения на 200 КБ для сайтов вакансий и форм</a>. Для оптимизации всей страницы используйте <a href=\"/ru/optimizirovat-izobrazheniya-dlya-sajta/\">оптимизатор изображений для сайта</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Хорошее ли качество у изображения на 200 КБ для сайта?","answer":"Да. При 200 КБ типичное фото для интернета выглядит почти как оригинал: детали товаров, текстуры и текст сохраняются. Это стандартный размер для блогов и магазинов именно потому, что качество при нём высокое, а страницы остаются быстрыми."},{"question":"Может ли фото с камеры на 24 мегапикселя чисто достичь 200 КБ?","answer":"Да, инструмент принимает файлы до 25 МБ и сжимает их до 200 КБ. Бинарный поиск находит лучшее качество, а масштабирование подключается, если нужно. Очень детальные фото могут слегка смягчиться, но при обычном просмотре это почти незаметно."},{"question":"Что выбрать при 200 КБ: JPG или WebP?","answer":"Для современных сайтов — WebP: при том же весе он чуть чище. Для порталов и систем с неизвестными правилами — JPG: его принимают везде. Если сомневаетесь, проверьте список принимаемых форматов места назначения."},{"question":"Удалит ли сжатие до 200 КБ метаданные моего изображения?","answer":"Да, сжатие удаляет скрытые метаданные, включая GPS-метки о месте съёмки. Это хорошо для конфиденциальности. Если метаданные нужны, сохраните копию оригинала."},{"question":"Что произойдёт, если моё изображение уже меньше 200 КБ?","answer":"Тогда сжимать его не нужно: файл уже укладывается в лимит. Инструмент может всё равно обработать его, но это добавит потери без пользы. Используйте файл как есть, если он выглядит хорошо."},{"question":"Можно ли сжать прозрачный PNG до 200 КБ, не потеряв прозрачность?","answer":"Да, если оставить формат PNG: прозрачность сохранится. Но фото в PNG может не уместиться в 200 КБ — тогда попробуйте WebP, который тоже поддерживает прозрачность и сжимается лучше. JPG не подходит: он прозрачность не хранит."}];
